insert into public.problems (slug, title, statement_md, difficulty, samples)
values ($cw$second-largest$cw$, $cw$Second Largest$cw$, $cw$Print the second largest **distinct** value in a list.

### Input
The first line contains an integer `n`. The second line contains `n` integers `a_i`.

### Output
Print the second largest distinct value, or `-1` if all values are equal.

### Constraints
- 1 ≤ n ≤ 100000
- 0 ≤ a_i ≤ 10^9$cw$, $cw$easy$cw$, $cw$[{"input":"5\n3 9 9 4 1","output":"4","explanation":"Distinct values are 9, 4, 3, 1."},{"input":"3\n5 5 5","output":"-1"}]$cw$::jsonb)
on conflict (slug) do update set
  title = excluded.title, statement_md = excluded.statement_md,
  difficulty = excluded.difficulty, samples = excluded.samples;
delete from public.problem_tests where problem_id = (select id from public.problems where slug = $cw$second-largest$cw$);
