insert into public.problems (slug, title, statement_md, difficulty, samples)
values ($cw$reverse-words$cw$, $cw$Reverse the Words$cw$, $cw$Print the words of a sentence in reverse order.

### Input
One line with words made of lowercase letters, separated by single spaces.

### Output
Print the same words in reverse order, separated by single spaces.

### Constraints
- 1 ≤ number of words ≤ 10000
- Each word has 1 to 20 letters.$cw$, $cw$easy$cw$, $cw$[{"input":"code wars is fun","output":"fun is wars code"},{"input":"solo","output":"solo"}]$cw$::jsonb)
on conflict (slug) do update set
  title = excluded.title, statement_md = excluded.statement_md,
  difficulty = excluded.difficulty, samples = excluded.samples;
delete from public.problem_tests where problem_id = (select id from public.problems where slug = $cw$reverse-words$cw$);
