insert into public.problems (slug, title, statement_md, difficulty, samples)
values ($cw$digit-root$cw$, $cw$Digit Root$cw$, $cw$Add up the digits of a number. If the result has more than one digit, repeat. Print the final single digit.

### Input
One line with a non-negative integer `n`. It can be far too large for a 64-bit type.

### Output
Print the single digit that remains.

### Constraints
- `n` has between 1 and 1000 digits and no leading zeros (except `0` itself).$cw$, $cw$easy$cw$, $cw$[{"input":"9875","output":"2","explanation":"9+8+7+5 = 29, 2+9 = 11, 1+1 = 2"},{"input":"0","output":"0"}]$cw$::jsonb)
on conflict (slug) do update set
  title = excluded.title, statement_md = excluded.statement_md,
  difficulty = excluded.difficulty, samples = excluded.samples;
delete from public.problem_tests where problem_id = (select id from public.problems where slug = $cw$digit-root$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$digit-root$cw$), 1, $cw$9$cw$, $cw$9$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$digit-root$cw$), 2, $cw$10$cw$, $cw$1$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$digit-root$cw$), 3, $cw$999999999999999999999999999999$cw$, $cw$9$cw$);
