values ((select id from public.problems where slug = $cw$digit-root$cw$), 4, $cw$$cw$, $cw$6$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$digit-root$cw$), 5, $cw$$cw$, $cw$9$cw$);

insert into public.problems (slug, title, statement_md, difficulty, samples)
values ($cw$peak-count$cw$, $cw$Count the Peaks$cw$, $cw$An element is a **peak** if it is strictly greater than both of its neighbours. The first and last elements are never peaks.

### Input
The first line contains an integer `n`. The second line contains `n` integers `a_i`.

### Output
Print the number of peaks.

### Constraints
- 1 ≤ n ≤ 100000
- -10^9 ≤ a_i ≤ 10^9$cw$, $cw$easy$cw$, $cw$[{"input":"7\n1 3 2 5 5 4 6","output":"1","explanation":"Only the 3 is a peak."},{"input":"2\n1 2","output":"0"}]$cw$::jsonb)
on conflict (slug) do update set
  title = excluded.title, statement_md = excluded.statement_md,
  difficulty = excluded.difficulty, samples = excluded.samples;
delete from public.problem_tests where problem_id = (select id from public.problems where slug = $cw$peak-count$cw$);
