insert into public.problems (slug, title, statement_md, difficulty, samples)
values ($cw$fewest-coins$cw$, $cw$Fewest Coins$cw$, $cw$You have an unlimited supply of coins of several values. Find the smallest number of coins that add up to exactly a target amount.

### Input
The first line contains two integers `n` and `amount`. The second line contains `n` distinct coin values `c_i`.

### Output
Print the minimum number of coins needed, or `-1` if the amount cannot be made.

### Constraints
- 1 ≤ n ≤ 100
- 0 ≤ amount ≤ 10000
- 1 ≤ c_i ≤ 10000$cw$, $cw$hard$cw$, $cw$[{"input":"3 11\n1 5 6","output":"2","explanation":"5 + 6. Greedy (6+5×1) would use more."},{"input":"2 7\n2 4","output":"-1","explanation":"Only even amounts are possible."}]$cw$::jsonb)
on conflict (slug) do update set
  title = excluded.title, statement_md = excluded.statement_md,
  difficulty = excluded.difficulty, samples = excluded.samples;
delete from public.problem_tests where problem_id = (select id from public.problems where slug = $cw$fewest-coins$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$fewest-coins$cw$), 1, $cw$1 0
7$cw$, $cw$0$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$fewest-coins$cw$), 2, $cw$1 10000
1$cw$, $cw$10000$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$fewest-coins$cw$), 3, $cw$3 6249
186 419 83$cw$, $cw$38$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$fewest-coins$cw$), 4, $cw$4 9999
2 4 6 8$cw$, $cw$-1$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$fewest-coins$cw$), 5, $cw$5 10000
3 7 11 4999 5003$cw$, $cw$456$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$fewest-coins$cw$), 6, $cw$6 9973
17 113 257 1009 2003 4001$cw$, $cw$13$cw$);

insert into public.problems (slug, title, statement_md, difficulty, samples)
values ($cw$grid-escape$cw$, $cw$Grid Escape$cw$, $cw$Find the fewest moves needed to walk from `S` to `E` in a grid. You can move up, down, left or right into any cell that is not a wall.

### Input
The first line contains two integers `r` and `c`. Each of the next `r` lines contains `c` characters: `.` (open), `#` (wall), `S` (start) or `E` (exit). There is exactly one `S` and one `E`.

### Output
Print the minimum number of moves, or `-1` if the exit cannot be reached.

### Constraints
- 1 ≤ r, c ≤ 500$cw$, $cw$hard$cw$, $cw$[{"input":"3 4\nS.#.\n.##.\n...E","output":"5","explanation":"Down, down, right, right, right."},{"input":"1 3\nS#E","output":"-1"}]$cw$::jsonb)
on conflict (slug) do update set
  title = excluded.title, statement_md = excluded.statement_md,
  difficulty = excluded.difficulty, samples = excluded.samples;
delete from public.problem_tests where problem_id = (select id from public.problems where slug = $cw$grid-escape$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$grid-escape$cw$), 1, $cw$1 2
SE$cw$, $cw$1$cw$);
insert into public.problem_tests (problem_id, ordinal, input, expected_output)
values ((select id from public.problems where slug = $cw$grid-escape$cw$), 2, $cw$3 3
S..
###
..E$cw$, $cw$-1$cw$);
